use pony_agent_core::agent::control_plane::HostControlPlaneBuilder;
use pony_agent_core::agent::runtime::TurnStreamEvent;
use pony_agent_core::agent::turn_flow::TurnEventSink;
use std::sync::Arc;
struct S;
impl TurnEventSink for S { fn emit(&self, _n: &str, _p: TurnStreamEvent) {} }
#[test]
fn sink_refs_released_on_turn_cleanup() {
    let cp = HostControlPlaneBuilder::new().build();
    let sink = Arc::new(S);
    cp.register_turn_event_sink("turn-x", sink.clone());
    cp.unregister_turn_event_sink("turn-x");
    assert_eq!(Arc::strong_count(&sink), 1, "StopEscalation.emitters still holds the sink after turn cleanup (NFR resource_release)");
}
RS
